<#
  Fix-VendorHistoryPaymentRadiusLocation.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  This script applies a batch of fixes on top of the previous
  Fix-PackagePhotoAndVendorDispatch.ps1 patch. Unlike that script (which did
  targeted find/replace on a couple of small blocks), this one does a full,
  backed-up REPLACEMENT of each of the 9 files below - the changes touch
  large, interleaved sections of each file. Each file's exact new content
  is embedded below as base64 of the RAW ORIGINAL BYTES (including each
  file's original BOM or lack of one), and is written back out byte-for-
  byte with no text re-encoding step, so there's no risk of double-BOM or
  encoding mangling.

  What this fixes:

  1. VENDOR HISTORY PAGE - overlapping icons
     The status pill + price were absolutely positioned on top of the title
     row with no reserved space, so they visually overlapped the package
     icon/title on narrower screens. Rebuilt as a normal flex layout with
     truncation so it can no longer overlap.

  2. VENDOR HISTORY PAGE - delete cancelled orders
     Added a "Remove from history" button (with a confirm step) that only
     appears on cancelled orders, scoped to the vendor's own vendor_id.

  3. PAYMENT GATE AFTER MATCH
     Previously there was no payment gate at all - a rider could slide
     straight to "picked up" the moment they were matched. Now: the rider's
     active-job screen shows a locked "Waiting for vendor payment" state
     until order.payment_status = 'paid'; the vendor's tracking page shows a
     prominent "Pay Now" button once matched; and /payment/page.jsx had two
     real bugs fixed - it redirected to a dead route (/track/ instead of
     /tracking/), and the OPay mock-payment path never actually set
     payment_status = 'paid' at all (it wrote a bogus status: 'confirmed'
     instead), so nothing would have unlocked the rider even after "paying."
     Both payment paths now go through the real /api/verify-payment endpoint.
     Also fixed: the driver-name lookup on the payment page queried
     riders.user_id using order.rider_id, which is actually a foreign key to
     riders.id - so it silently failed and always fell back to "Carrier".

  4. EXPANDABLE JOB CARD
     Riders can now tap "View Full Details" on an incoming job to reveal
     item description, delivery type, recipient info, and pickup/dropoff
     notes that weren't shown on the collapsed card before.

  5. DOUBLE-CONFIRM ACCEPT
     Tapping "Accept Signal" now opens a second explicit "Yes, This Job Is
     Mine" / "Cancel" step instead of committing immediately.

  6. REAL EXPANDING SEARCH RADIUS
     Previously the radius only ever expanded if the customer happened to
     keep the send-package confirmation screen open in the same tab -
     vendor-created orders never expanded at all. Added a real expand +
     re-dispatch polling loop to the tracking page itself (used by both
     vendor and customer views), and pointed vendor order creation at that
     live tracking screen instead of a static history list.

  7. "USE MY LOCATION" RELIABILITY
     The app had four different geolocation implementations, several of
     them raw one-shot getCurrentPosition() calls with no fallback (one was
     even trying a weak method first and eating its full 10s timeout before
     falling back to the good one). Standardized every location button on
     the one reliable, tiered helper (getReliableLocation) that already
     existed but wasn't consistently used.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-VendorHistoryPaymentRadiusLocation.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-batch2"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FullFile($relPath, $base64Content, $label) {
    $full = Get-FullPath $relPath
    if (-not (Test-Path -LiteralPath $full)) {
        Write-Host "  SKIP (not found): $relPath - is this the right repo root?" -ForegroundColor Yellow
        return
    }
    Backup-Path $full
    $bytes = [System.Convert]::FromBase64String($base64Content)
    # Raw byte write - no text/encoding round-trip, so each file's original
    # BOM (or lack of one) is preserved exactly as it was, byte for byte.
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  REPLACED: $label" -ForegroundColor Green
}

if (-not (Test-Path -LiteralPath (Get-FullPath "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

Write-Host "`nApplying vendor-history / payment-gate / radius / location fixes:" -ForegroundColor Cyan

